import { nearToYocto } from "near-api-js";
import { OPERATOR_ACCOUNT_ID, NEW_ACCOUNT_NEAR, MIN_ACCOUNT_NEAR } from "../config.js";
import { findWalletRecord, createWalletRecord, walletKey } from "../walletStore.js";
import { accountExists, availableBalance, operatorAccount, signingAccount } from "./client.js";

/**
 * Each chat user gets a named NEAR account under the operator account, for
 * example tg123456.orbits.testnet, created on first use. Its key is
 * generated by the bot and stored encrypted (walletStore.js): a custodial
 * model, as in the EVM bot.
 */

const PREFIX = { telegram: "tg", discord: "dc", slack: "sl" };

/** The NEAR account a platform user gets, e.g. ("telegram", 123456) -> "tg123456.orbits.testnet". */
export function userAccountId(platform, platformUserId) {
  const prefix = PREFIX[platform];
  if (!prefix) throw new Error(`No NEAR account prefix for platform "${platform}"`);
  const local = String(platformUserId).toLowerCase().replace(/[^a-z0-9]/g, "");
  if (!local) throw new Error(`Can't make a NEAR account name from user id "${platformUserId}"`);
  const accountId = `${prefix}${local}.${OPERATOR_ACCOUNT_ID}`;
  if (accountId.length > 64) throw new Error(`NEAR account name too long: ${accountId}`);
  return accountId;
}

/** This user's existing account ID, or null. Creates nothing. */
export async function findUserAccountId(platform, platformUserId) {
  return (await findWalletRecord(platform, platformUserId))?.account_id ?? null;
}

/**
 * This user's account, signing with their key, created first if needed:
 * the key is stored, then the account is created on chain with
 * NEW_ACCOUNT_NEAR from the operator. Both steps are safe to repeat.
 */
export async function getOrCreateUserAccount(platform, platformUserId) {
  let record = await findWalletRecord(platform, platformUserId);
  if (!record) record = await createWalletRecord(platform, platformUserId, userAccountId(platform, platformUserId));
  if (!(await accountExists(record.account_id))) {
    await operatorAccount().createSubAccount({
      accountOrPrefix: record.account_id,
      publicKey: record.public_key,
      nearToTransfer: nearToYocto(NEW_ACCOUNT_NEAR),
    });
  }
  return signingAccount(record.account_id, await walletKey(record));
}

/**
 * Tops `accountId` back up to NEW_ACCOUNT_NEAR from the operator when its
 * spendable balance is below MIN_ACCOUNT_NEAR, so it can pay gas. The
 * operator pays gas and storage only, never the amounts users send.
 */
export async function ensureGas(accountId) {
  const available = await availableBalance(accountId);
  const min = nearToYocto(MIN_ACCOUNT_NEAR);
  if (available >= min) return;
  await operatorAccount().transfer({ receiverId: accountId, amount: nearToYocto(NEW_ACCOUNT_NEAR) - available });
}
